<div class="panel form-panel"><p class="eyebrow">CLIENT DIRECTORY</p><h2>Create a new user</h2><?=form_open('admin/users/create')?><div class="form-grid"><label>First name<input name="first_name" required></label><label>Last name<input name="last_name" required></label><label>Email address<input type="email" name="email" required></label><label>Temporary password<input type="password" name="password" required></label><label>Phone number<input name="phone"></label><label>Country<input name="country"></label></div><button class="button">Create customer</button><?=form_close()?></div>
